/**
 * Checks (default) or updates (`--update`) the committed API reports of the published packages:
 * one `api-report/<entry>.api.md` per public entry, generated by API Extractor from the built
 * declaration files in `dist/`. A public type change without an updated report fails the check,
 * which turns semver-relevant changes into a visible diff in code review.
 *
 * Usage: `pnpm api:check` / `pnpm api:update` at the repository root. Both build the packages
 * first, so the reports never describe a stale `dist/`.
 */
import { execFileSync } from 'node:child_process';
import { existsSync, mkdirSync, mkdtempSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join, relative } from 'node:path';

import {
  Extractor,
  ExtractorConfig,
  ExtractorLogLevel,
  type ExtractorMessage,
  type IConfigFile,
} from '@microsoft/api-extractor';

import { publishedPackages, repoRoot } from './packages.ts';

const update = process.argv.includes('--update');
const packages = publishedPackages();

execFileSync(
  'pnpm',
  [...packages.flatMap((pkg) => ['--filter', pkg.name]), '--silent', 'run', 'build'],
  { cwd: repoRoot, stdio: 'inherit' },
);

// The temp report is what a check compares against the committed one; it is never kept.
const tempRoot = mkdtempSync(join(tmpdir(), 'oakestra-api-report-'));

/**
 * Only the declaration files are analysed, so the compiler needs no project settings beyond what
 * resolving React and DOM types takes.
 *
 * In the workspace `@oakestra/api` resolves to its TypeScript sources (package.json `exports`),
 * which API Extractor rejects. `paths` sends every published package to its built declarations
 * instead, the files a consumer gets. They are reached through the importer's own node_modules
 * symlink and `preserveSymlinks` keeps that path, so the import counts as an external package and
 * the SDK report names `@oakestra/api` instead of inlining its types.
 */
function compilerOptionsFor(consumerDir: string) {
  const paths = Object.fromEntries(
    packages.flatMap((pkg) =>
      pkg.entries.map((entry) => [
        entry.name === 'index' ? pkg.name : `${pkg.name}/${entry.name}`,
        [join(consumerDir, 'node_modules', pkg.name, entry.types)],
      ]),
    ),
  );
  return {
    target: 'ES2023',
    lib: ['ES2023', 'DOM', 'DOM.Iterable'],
    module: 'ESNext',
    moduleResolution: 'Bundler',
    jsx: 'react-jsx',
    strict: true,
    skipLibCheck: true,
    preserveSymlinks: true,
    paths,
    types: [],
  };
}

const failures: string[] = [];

/** Shows in the CI log what changed, so nobody has to run the update to find out. */
function printDiff(committed: string, generated: string): void {
  try {
    execFileSync(
      'diff',
      [
        '-u',
        '--label',
        relative(repoRoot, committed),
        '--label',
        'built declarations',
        existsSync(committed) ? committed : '/dev/null',
        generated,
      ],
      { stdio: 'inherit' },
    );
  } catch {
    // diff exits with 1 when the files differ, which is the expected case here.
  }
}

try {
  for (const pkg of packages) {
    for (const entry of pkg.entries) {
      const label = `${pkg.name}${entry.name === 'index' ? '' : `/${entry.name}`}`;
      const mainEntryPointFilePath = join(pkg.dir, entry.types);
      if (!existsSync(mainEntryPointFilePath)) {
        failures.push(`${label}: ${relative(repoRoot, mainEntryPointFilePath)} was not built`);
        continue;
      }

      mkdirSync(join(pkg.dir, 'api-report'), { recursive: true });
      const configObject: IConfigFile = {
        projectFolder: pkg.dir,
        mainEntryPointFilePath,
        compiler: {
          overrideTsconfig: {
            compilerOptions: compilerOptionsFor(pkg.dir),
            files: [mainEntryPointFilePath],
          },
        },
        apiReport: {
          enabled: true,
          reportFileName: entry.name,
          reportFolder: join(pkg.dir, 'api-report'),
          reportTempFolder: join(tempRoot, pkg.name, entry.name),
          // Unexported types used by public signatures are still part of the contract.
          includeForgottenExports: true,
        },
        docModel: { enabled: false },
        dtsRollup: { enabled: false },
        tsdocMetadata: { enabled: false },
        newlineKind: 'lf',
        messages: {
          compilerMessageReporting: { default: { logLevel: ExtractorLogLevel.Error } },
          extractorMessageReporting: {
            default: { logLevel: ExtractorLogLevel.Warning },
            // Release tags (@public, @beta) are not used here; semver covers every export.
            'ae-missing-release-tag': { logLevel: ExtractorLogLevel.None },
            'ae-undocumented': { logLevel: ExtractorLogLevel.None },
            // includeForgottenExports already puts those declarations into the report. The
            // warnings would add comments with line numbers of dist files, which change with
            // every unrelated edit.
            'ae-forgotten-export': { logLevel: ExtractorLogLevel.None, addToApiReportFile: false },
          },
          // The doc comments are written for people and editors, not checked as TSDoc.
          tsdocMessageReporting: { default: { logLevel: ExtractorLogLevel.None } },
        },
      };

      const config = ExtractorConfig.prepare({
        configObject,
        configObjectFullPath: undefined,
        packageJsonFullPath: join(pkg.dir, 'package.json'),
      });

      const messages: string[] = [];
      const result = Extractor.invoke(config, {
        localBuild: update,
        messageCallback: (message: ExtractorMessage) => {
          // console-* messages are API Extractor's own advice about the report files (changed,
          // created, copy it here); the result flags below cover them with a clearer hint.
          if (
            !String(message.messageId).startsWith('console-') &&
            (message.logLevel === ExtractorLogLevel.Error ||
              message.logLevel === ExtractorLogLevel.Warning)
          ) {
            messages.push(message.formatMessageWithLocation(pkg.dir));
          }
          message.handled = true;
        },
      });

      const reportPath = relative(repoRoot, join(pkg.dir, 'api-report', `${entry.name}.api.md`));
      if (messages.length > 0) failures.push(`${label}:\n  ${messages.join('\n  ')}`);
      if (result.apiReportChanged && !update) {
        failures.push(`${label}: public API differs from ${reportPath}`);
        printDiff(
          join(repoRoot, reportPath),
          join(config.reportTempFolder, `${entry.name}.api.md`),
        );
      } else if (result.apiReportChanged) {
        console.log(`updated ${reportPath}`);
      } else {
        console.log(`unchanged ${reportPath}`);
      }
    }
  }
} finally {
  rmSync(tempRoot, { recursive: true, force: true });
}

if (failures.length > 0) {
  console.error(`\n${failures.join('\n')}`);
  if (!update) {
    console.error(
      '\nIf the change is intended, run `pnpm api:update` and commit the reports. Removing or ' +
        'changing an export is a breaking change for addons; see docs/addons/packaging.md.',
    );
  }
  process.exit(1);
}
